package main

import (
	"fmt"
	"log"
)

func Init(val int) (int, error) {
	if val < 0 {
		return 0, fmt.Errorf("invalid value: %d", val)
	}
	return val * 9, nil
}

func main() {
	result, err := Init(20)
	if err != nil {
		log.Fatal(err)
	}
